WITH filtered AS (SELECT *, COALESCE(quantity, 0) AS quantity_filled FROM inventory WHERE last_restock > DATE '2023-07-14') SELECT CASE WHEN quantity_filled >= 77 THEN 'HIGH' ELSE 'LOW' END AS quantity_filled_tier, DATE_TRUNC('QUARTER', last_restock) AS quarter_start, SUM(quantity) AS total_quantity, SUM(quantity_filled) AS total_quantity_filled, APPROX_PERCENTILE(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, STDDEV_SAMP(quantity) AS quantity_stddev, COUNT(DISTINCT product_id) AS distinct_product_ids FROM filtered GROUP BY GROUPING SETS ((CASE WHEN quantity_filled >= 77 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('QUARTER', last_restock)), (CASE WHEN quantity_filled >= 77 THEN 'HIGH' ELSE 'LOW' END), ()) HAVING total_quantity_filled >= 0 ORDER BY total_quantity DESC NULLS FIRST
